<script setup lang="ts">
import { ref,computed,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { usePlatform } from '../stores/platform'
import type { Question } from '../domain/types'
import { knowledgePoints,professions } from '../mocks/seed'
import { csv } from '../utils/files'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
import CatalogTree from '../components/CatalogTree.vue'
import { catalogPath,matchesCatalog,catalogLabels,catalogKinds,catalogActive,type CatalogNode } from '../domain/catalog'
const s=usePlatform(),route=useRoute(),router=useRouter();const structure=computed(()=>route.params.page==='structure');const kind=ref(typeof route.query.kind==='string'?route.query.kind:'全部'),bank=ref('全部题库'),type=ref('全部题型'),status=ref('全部状态'),search=ref(''),currentPage=ref(1),selected=ref<string[]>([]),detail=ref<Question|null>(null),importOpen=ref(false),importRows=ref<any[]>([]),importErrors=ref<string[]>([]),nodeName=ref(''),selectedNode=ref<string|null>(typeof route.query.node==='string'?route.query.node:null),nodeDialog=ref(false),editingNode=ref<string|undefined>(),parentNode=ref<string|null>(null),deleteNode=ref<CatalogNode|null>(null)
const catalog=computed(()=>s.data.catalog||[])
const currentNode=computed(()=>catalog.value.find(n=>n.id===selectedNode.value))
const path=computed(()=>catalogPath(catalog.value,selectedNode.value))
const counts=computed(()=>Object.fromEntries(catalog.value.map(n=>[n.id,s.data.questions.filter(q=>s.canReadQuestion(q)).filter(q=>matchesCatalog(q,catalog.value,n.id)).length])))
const childNodes=computed(()=>currentNode.value?.kind==='knowledge'?[currentNode.value]:catalog.value.filter(n=>n.parentId===selectedNode.value))
const nextKind=computed(()=>catalogKinds[currentNode.value?catalogKinds.indexOf(currentNode.value.kind)+1:0])
watch(()=>catalog.value.map(n=>n.id).join(','),()=>{if(selectedNode.value&&!catalog.value.some(n=>n.id===selectedNode.value))selectedNode.value=null})
watch(selectedNode,id=>{currentPage.value=1;selected.value=[];router.replace({query:{...route.query,node:id||undefined}})})
watch(()=>route.query.node,id=>{selectedNode.value=typeof id==='string'&&catalog.value.some(n=>n.id===id)?id:null})
function openNode(node?:CatalogNode){editingNode.value=node?.id;parentNode.value=node?node.parentId:selectedNode.value;nodeName.value=node?.name||'';nodeDialog.value=true}
function saveNode(){s.run(()=>{s.saveCatalogNode(parentNode.value,nodeName.value,editingNode.value);nodeDialog.value=false})}
function removeNode(){s.run(()=>{s.deleteCatalogNode(deleteNode.value!.id);if(selectedNode.value===deleteNode.value!.id)selectedNode.value=deleteNode.value!.parentId;deleteNode.value=null})}
function showQuestions(id:string){router.push({path:'/bank/questions',query:{node:id}})}
const filtered=computed(()=>s.data.questions.filter(q=>s.canReadQuestion(q)).filter(q=>(kind.value==='全部'||q.kind===kind.value)&&(bank.value==='全部题库'||q.bank===bank.value)&&(type.value==='全部题型'||q.type===type.value)&&(status.value==='全部状态'||q.status===status.value)&&matchesCatalog(q,catalog.value,selectedNode.value)&&(!search.value||q.title.includes(search.value)||q.id.includes(search.value))))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10)));const shown=computed(()=>filtered.value.slice((Math.min(currentPage.value,pages.value)-1)*10,Math.min(currentPage.value,pages.value)*10))
function choose(id:string){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
function exportList(){csv('题库资源清单.csv',[['题号','题干','题型','知识点','题库','状态','版本'],...filtered.value.map(q=>[q.id,q.title,q.type,q.knowledge,q.bank,q.status,q.version])]);s.audit('题库管理','导出资源清单',`${filtered.value.length}条`)}
async function template(){const x=await import('xlsx');const ws=x.utils.json_to_sheet([{题干:'请选择正确的作业准备方式（演示）',题型:'单选题',知识点:knowledgePoints[0],选项A:'检查工具',选项B:'忽略检查',选项C:'直接操作',选项D:'不做记录',答案:'A',解析:'按标准流程准备',题库:'母题库'}]);const wb=x.utils.book_new();x.utils.book_append_sheet(wb,ws,'试题导入');x.writeFile(wb,'试题导入模板.xlsx')}
async function importFile(event:Event){importErrors.value=[];importRows.value=[];const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>5*1024*1024){importErrors.value=['文件过大，请使用5MB以内的演示模板'];return}try{const x=await import('xlsx');const wb=x.read(await file.arrayBuffer());const rows=x.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]!]!) as any[];if(!rows.length||rows.length>200)throw new Error('模板应包含1～200行试题');rows.forEach((r,i)=>{if(!r.题干||!r.答案||!['单选题','多选题','判断题'].includes(r.题型))importErrors.value.push(`第${i+2}行：缺少题干、答案或题型不支持`);else if(!/^[ABCD](,[ABCD])*$/.test(String(r.答案)))importErrors.value.push(`第${i+2}行：答案请使用A或A,B格式`);else if(r.题型==='单选题'&&String(r.答案).includes(','))importErrors.value.push(`第${i+2}行：单选题只能设置一个答案`);else if(r.题型==='判断题'&&!['A','B'].includes(String(r.答案)))importErrors.value.push(`第${i+2}行：判断题答案只能是A或B`);else if(r.题型!=='判断题'&&['选项A','选项B','选项C','选项D'].some(k=>!r[k]))importErrors.value.push(`第${i+2}行：请完整填写四个选项`);else if(s.data.questions.some(q=>q.title===r.题干)||rows.slice(0,i).some(q=>q.题干===r.题干))importErrors.value.push(`第${i+2}行：题干完全重复`)});importRows.value=rows}catch(e){importErrors.value=[e instanceof Error?e.message:'文件解析失败，请使用提供的Excel模板']}}
function confirmImport(){s.run(()=>{if(importErrors.value.length||!importRows.value.length)throw new Error('请先上传并修正模板');for(const r of importRows.value){s.saveQuestion({id:'',title:r.题干,type:r.题型,kind:'理论',profession:professions[0]!,level:'三级 / 高级工',subject:'专业理论',knowledge:r.知识点||knowledgePoints[0],bank:['母题库','子题库','通用题库'].includes(r.题库)?r.题库:'母题库',difficulty:'中等',status:'草稿',author:s.actor,version:1,options:r.题型==='判断题'?['正确','错误']:[r.选项A,r.选项B,r.选项C,r.选项D],answers:String(r.答案).split(',').map(v=>String(v.charCodeAt(0)-65)),analysis:r.解析||'',rubric:[],preparation:'',venue:'',history:[]})}s.notify(`已导入${importRows.value.length}道草稿，需审核后入库`);importOpen.value=false})}
function buildManual(){s.run(()=>{s.manualPaper('专家自定义试卷',selected.value);router.push('/papers')})}
</script>
<template>
  <PageHead :title="structure?'知识结构管理':'题库资源'" :subtitle="structure?'按照职业工种、技能等级、科目与知识点组织资源。':'理论与技能题库统一检索，母题库、子题库和通用题库按需复用。'" eyebrow="题库管理 / 资源中心"><button v-if="!structure&&s.can('bank')" class="button" @click="importOpen=true;importRows=[];importErrors=[]"><Icon name="Upload" :size="16"/>导入试题</button><button v-if="!structure&&(s.can('bank')||s.can('author'))" class="button primary" @click="router.push('/authoring/editor')"><Icon name="Plus" :size="16"/>新建试题</button></PageHead>
  <div class="bank-layout"><aside class="panel tree-panel"><div class="panel-head"><h3>{{structure?'知识结构树':'资源目录树'}}</h3><Icon name="Network" :size="17"/></div><CatalogTree v-model="selectedNode" :nodes="catalog" :counts="counts" :total="s.data.questions.length"/><div class="tree-note"><Icon name="Info" :size="15"/>工种 → 等级 → 科目 → 知识点。数量为目录下全部试题，右侧可叠加筛选。</div></aside>
  <section class="panel bank-main"><div class="catalog-breadcrumb"><button @click="selectedNode=null">全部资源</button><template v-for="n in path" :key="n.id"><Icon name="ChevronRight" :size="13"/><button @click="selectedNode=n.id">{{n.name}}</button></template><span v-if="currentNode&&!catalogActive(catalog,currentNode.id)" class="muted">此分支已停用</span></div><template v-if="!structure"><div class="tabs"><button v-for="k in ['全部','理论','技能']" :class="{active:kind===k}" @click="kind=k;currentPage=1">{{k==='全部'?'全部资源':k+'题库'}}</button><button class="tabs-right" @click="exportList"><Icon name="Download" :size="16"/>导出清单</button></div><div class="filter-bar wrap"><div class="input-icon"><Icon name="Search" :size="16"/><input v-model="search" placeholder="输入题干或题号…" @input="currentPage=1"/></div><select v-model="bank" @change="currentPage=1"><option>全部题库</option><option>母题库</option><option>子题库</option><option>通用题库</option></select><select v-model="type" @change="currentPage=1"><option>全部题型</option><option v-for="t in ['单选题','多选题','判断题','简答题','实操步骤题','评分表题']">{{t}}</option></select><select v-model="status" @change="currentPage=1"><option>全部状态</option><option>已入库</option><option>草稿</option><option>已停用</option></select></div><div v-if="selected.length&&s.can('assemble')" class="selection-bar">已选择 {{selected.length}} 道试题 <button class="text-button" @click="buildManual">按选题固定组卷</button><button class="text-button" @click="selected=[]">清空选择</button></div><div class="table-scroll"><table><thead><tr><th></th><th>试题内容</th><th>题型 / 难度</th><th>来源题库</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="q in shown" :key="q.id"><td><input type="checkbox" :checked="selected.includes(q.id)" :disabled="q.status!=='已入库'" :aria-label="'选择'+q.id" @change="choose(q.id)"/></td><td><button class="cell-link" @click="detail=q">{{q.title}}</button><small>{{q.id}} · {{q.knowledge}} · V{{q.version}}</small></td><td>{{q.type}}<small>{{q.difficulty}}</small></td><td><span class="bank-pill" :class="q.bank==='母题库'?'blue':q.bank==='子题库'?'teal':'violet'">{{q.bank}}</span></td><td><Badge :text="q.status"/></td><td><button class="text-button" @click="detail=q">详情</button></td></tr></tbody></table></div><Empty v-if="!filtered.length"/><div class="pagination"><span>共 {{filtered.length}} 条 · 每页 10 条</span><div><button class="button small" :disabled="currentPage<=1" @click="currentPage--"><Icon name="ChevronLeft" :size="15"/></button><span>{{Math.min(currentPage,pages)}} / {{pages}}</span><button class="button small" :disabled="currentPage>=pages" @click="currentPage++"><Icon name="ChevronRight" :size="15"/></button></div></div></template>
  <template v-else><div class="panel-head"><h3>{{currentNode?.name||'职业知识体系'}}</h3><span class="subtle-label">{{currentNode?catalogLabels[currentNode.kind]:'根目录'}} · {{childNodes.length}}个节点</span></div><div class="filter-bar wrap"><button v-if="nextKind" class="button primary" @click="openNode()"><Icon name="Plus" :size="16"/>新增{{catalogLabels[nextKind]}}</button><button v-if="currentNode" class="button" @click="openNode(currentNode)">重命名当前节点</button><button v-if="currentNode" class="button" @click="s.run(()=>s.toggleCatalogNode(currentNode!.id))">{{currentNode.disabled?'启用':'停用'}}当前节点</button></div><div class="table-scroll"><table><thead><tr><th>节点名称 / 编码</th><th>层级</th><th>关联题目</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="n in childNodes" :key="n.id"><td><button class="cell-link" @click="selectedNode=n.id">{{n.name}}</button><small>{{n.id}}</small></td><td>{{catalogLabels[n.kind]}}</td><td>{{counts[n.id]||0}}</td><td><Badge :text="catalogActive(catalog,n.id)?'启用':'已停用'"/></td><td><div class="catalog-actions"><button class="text-button" @click="showQuestions(n.id)">查看试题</button><button class="text-button" @click="openNode(n)">重命名</button><button class="text-button" @click="s.run(()=>s.toggleCatalogNode(n.id))">{{n.disabled?'启用':'停用'}}</button><button class="text-button" @click="deleteNode=n">删除</button></div></td></tr></tbody></table></div><Empty v-if="!childNodes.length"/><div class="notice">选择父级可新增下一级。更名同步题库，历史试卷快照保留；停用分支不可用于新命题，有引用或子节点的目录不能删除。</div></template></section></div>
  <Modal v-if="nodeDialog" :title="editingNode?'重命名目录节点':'新增目录节点'" @close="nodeDialog=false"><p class="muted">所属目录：{{catalogPath(catalog,parentNode).map(n=>n.name).join(' / ')||'职业知识体系'}}</p><label class="field">节点名称<input v-model="nodeName" maxlength="50" placeholder="请输入节点名称" @keyup.enter="saveNode"/></label><template #footer><button class="button" @click="nodeDialog=false">取消</button><button class="button primary" @click="saveNode">保存节点</button></template></Modal>
  <Modal v-if="deleteNode" title="删除空目录节点" @close="deleteNode=null"><p>确认删除“{{deleteNode.name}}”？已有试题、试卷或子节点引用时将拒绝删除，可使用停用保留历史。</p><template #footer><button class="button" @click="deleteNode=null">取消</button><button class="button danger-outline" @click="removeNode">确认删除节点</button></template></Modal>
  <Modal v-if="detail" :title="'试题详情 · '+detail.id" wide @close="detail=null"><div class="tag-list"><Badge :text="detail.status"/><span>{{detail.type}}</span><span>{{detail.bank}}</span><span>{{detail.knowledge}}</span></div><h3 class="detail-title">{{detail.title}}</h3><div v-for="(o,i) in detail.options" class="preview-option" :class="{correct:detail.answers.includes(String(i))}">{{String.fromCharCode(65+i)}}. {{o}}<Icon v-if="detail.answers.includes(String(i))" name="Check" :size="16"/></div><div class="notice">{{detail.analysis}}</div><template v-if="detail.kind==='技能'"><h4>考生准备</h4><p>{{detail.preparation}}</p><h4>考场准备</h4><p>{{detail.venue}}</p><div class="rubric-list"><p v-for="r in detail.rubric">{{r.label}}<strong>{{r.max}} 分</strong></p></div></template><h4>版本轨迹</h4><div class="timeline compact"><div v-for="h in detail.history.slice().reverse()"><i></i><strong>{{h.action}} · V{{h.version}}</strong><p>{{h.note}}</p><small>{{h.actor}} · {{h.time}}</small></div></div><template #footer><button v-if="s.can('bank')&&detail.status==='已入库'" class="button danger-outline" @click="s.run(()=>s.stopQuestion(detail!.id));detail=null">停用资源</button><button v-if="s.canEditQuestion(detail)&&['草稿','已退回','已入库','已停用'].includes(detail.status)" class="button primary" @click="router.push({path:'/authoring/editor',query:{id:detail.id}});detail=null">{{detail.status==='已入库'?'创建修订版本':'编辑试题'}}</button></template></Modal>
  <Modal v-if="importOpen" title="试题模板导入" wide @close="importOpen=false"><div class="notice">支持提供的Excel标准模板，单次最多200道。导入为草稿，经审核后入库；Word及历史复杂格式尚未接入。</div><div class="import-zone"><Icon name="FileSpreadsheet" :size="40"/><h3>上传 Excel 试题文件</h3><input type="file" accept=".xlsx,.xls" @change="importFile"/><button class="text-button" @click="template">下载标准模板</button></div><div v-if="importErrors.length" class="notice warning"><p v-for="e in importErrors">{{e}}</p></div><div v-else-if="importRows.length" class="notice success">解析成功，共{{importRows.length}}道，格式检查通过。</div><div class="table-scroll" v-if="importRows.length"><table><thead><tr><th>题干</th><th>题型</th><th>答案</th></tr></thead><tbody><tr v-for="r in importRows.slice(0,5)"><td>{{r.题干}}</td><td>{{r.题型}}</td><td>{{r.答案}}</td></tr></tbody></table></div><template #footer><button class="button" @click="importOpen=false">取消</button><button class="button primary" :disabled="!importRows.length||!!importErrors.length" @click="confirmImport">确认导入草稿</button></template></Modal>
</template>
